cd /workspace && python3 -c "
import docx,re
d=docx.Document('output/offer_letter_filled.docx')
markers=[]
for s in d.sections:
    for part in (s.header,s.first_page_header,s.even_page_header,s.footer,s.first_page_footer,s.even_page_footer):
        if part is None: continue
        for p in part.paragraphs:
            if '{{' in p.text: markers.append(p.text)
print('header/footer leftover markers:', markers)
print('OK' if not markers else 'FAIL')
"
